import styles from '@/app/page.module.css';
import { useRouter } from "next/router";

export default function Custom404() {
  const router = useRouter();
  const lang = router.query.lang as string | undefined;
  const isFrench = lang === "fr-FR";

  return (
    <div className={styles.container4}>
      <div>
        <h1 className={styles.headeronwhiteX2}>404</h1>
        <h2 className={styles.headeronwhite}>
          {isFrench ? "Oups, cette page n'existe pas !" : "Oops, this page does not exist!"}
        </h2>
        <p className={styles.bodyonwhite}>
          {isFrench
            ? <>La page que vous recherchez est introuvable.<br />Retournez à l'accueil pour continuer votre expérience Vyft.</>
            : <>The page you are looking for cannot be found.<br />Go back to the homepage to continue your Vyft experience.</>
          }
        </p>
        <a href={isFrench ? "/fr-FR" : "/en-EN"} className={styles.modalButton} style={{marginTop: 30}}>
          {isFrench ? "Retour à l'accueil" : "Back to homepage"}
        </a>
      </div>
    </div>
  );
}